parameterdescription.para:
HMACコールバックを作成するにはオプションです。 Example char*config="path/to/config/example.conf";
inttime=//Somesufficienttimeoutvalue;

if(wc_InitNetRandom(config,NULL,time)!=0)
{
//Someerroroccurred
}

simplesect.para:
BAD_MUTEX_E Wnr_Mutexでミューテックスをロックするエラー Example intret=wc_FreeNetRandom();
if(ret!=0)
{
//Handletheerror
}

RNG_FAILURE_E wc_rng_generateBlock：デフォルトエラーです。RNGのステータスはもともとOKではなく、drbg_failedに設定されています Example RNGrng;
intret;

#ifdefHAVE_CAVIUM
ret=wc_InitRngCavium(&rng,CAVIUM_DEV_ID);
if(ret!=0){
printf(“RNGNitroxinitfordevice:%dfailed”,CAVIUM_DEV_ID);
return-1;
}
#endif
ret=wc_InitRng(&rng);
if(ret!=0){
printf(“RNGinitfailed”);
return-1;
}

parameterdescription.para:
ブロックがコピーされるバッファ Example RNGrng;
intsz=32;
byteblock[sz];

intret=wc_InitRng(&rng);
if(ret!=0){
return-1;//initofrngfailed!
}

ret=wc_RNG_GenerateBlock(&rng,block,sz);
if(ret!=0){
return-1;//generatingblockfailed!
}

detaileddescription.para:
WC_RNG 成功の構造 


NULL 誤りに 



heap



ヒープ識別子へのポインタ 




nonce



nonceを含むバッファへのポインタ Example RNGrng;
bytenonce[]={initializenonce};
word32nonceSz=sizeof(nonce);

wc_rng_new(&nonce,nonceSz,&heap);





wc_InitRng 


wc_rng_free 


wc_FreeRng 


wc_RNG_HealthTest

wc_rng_generateBlockを呼び出して、疑似ランダムデータのバイトをbにコピーします。必要に応じてRNGが再販されます。 
0 成功した 


BAD_FUNC_ARG 入力はNULLまたはSZがMAX_REQUEST_LENを超えています 


DRBG_CONT_FIPS_E hash_genはdrbg_cont_failureを返しました 


RNG_FAILURE_E デフォルトのエラーRNGのステータスはもともとOKではなく、drbg_failedに設定されています 



rng



乱数発生器はWC_INITRNGで初期化された Example RNGrng;
intsz=32;
byteb[1];

intret=wc_InitRng(&rng);
if(ret!=0){
return-1;//initofrngfailed!
}

ret=wc_RNG_GenerateByte(&rng,b);
if(ret!=0){
return-1;//generatingblockfailed!
}





wc_InitRngCavium 


wc_InitRng 


wc_RNG_GenerateBlock 


wc_FreeRng 


wc_RNG_HealthTest


WC_RNG structure on success 


NULL on error



heap



pointer to a heap identifier 




nonce



pointer to the buffer containing the nonce 




nonceSz



length of the nonce



Example RNGrng;
bytenonce[]={initializenonce};
word32nonceSz=sizeof(nonce);

wc_rng_new(&nonce,nonceSz,&heap);

simplesect.para:
RNG_FAILURE_E DRBGの割り当て解除に失敗しました Example RNGrng;
intret=wc_InitRng(&rng);
if(ret!=0){
return-1;//initofrngfailed!
}

intret=wc_FreeRng(&rng);
if(ret!=0){
return-1;//freeofrngfailed!
}

parameterdescription.para:
SEADRANDOMが設定されている場合は、Entropybに播種されたランダムなデータに初期化され、それ以外の場合はEntropya Example byteoutput[SHA256_DIGEST_SIZE*4];
constbytetest1EntropyB[]=....;//testinputforreseedfalse
constbytetest1Output[]=....;//testvector:expectedoutputof
//reseedfalse
ret=wc_RNG_HealthTest(0,test1Entropy,sizeof(test1Entropy),NULL,0,
output,sizeof(output));
if(ret!=0)
return-1;//healthtestwithoutreseedfailed

if(XMEMCMP(test1Output,output,sizeof(output))!=0)
return-1;//comparetotestvectorfailed:unexpectedoutput

constbytetest2EntropyB[]=....;//testinputforreseed
constbytetest2Output[]=....;//testvectorexpectedoutputofreseed
ret=wc_RNG_HealthTest(1,test2EntropyA,sizeof(test2EntropyA),
test2EntropyB,sizeof(test2EntropyB),
output,sizeof(output));

if(XMEMCMP(test2Output,output,sizeof(output))!=0)
return-1;//comparetotestvectorfailed
